import { useQuery } from 'react-query';
import SessionTableApi from 'services/sessionTableApi';
import FilterApi from 'services/filterApi';


export const useSessionScreenList = (postBody) => {
  return useQuery('sessionScreens', () =>
    SessionTableApi.fetchSessionScreenNames(postBody), {
    enabled: !!postBody?.sessionid,
  }
  );
};

export const useAppScreenList = (postBody, options) =>
  useQuery(
    'appScreens',
    () => FilterApi.getPropertiesWithCancelToken(postBody),
    options
  );

export const useAppScreenListWithSearch = (postBody, isApiCall) =>
  useQuery(
    ['appScreensApi', postBody.screenname, isApiCall],
    () => FilterApi.getPropertiesWithCancelToken(postBody),
    {
      enabled: isApiCall,
    }
  );
