export const newFilter = rule => async (dispatch, getState) => {
  const rulelist = [...getState().videoSettingReducer]
  rulelist.push(rule)
  dispatch(gotListVideoRecording(rulelist))
  dispatch(selectedRule(rule))
}

export const resendInvite = (appId, data) => async (dispatch, getState) => {
  const csrf = await dispatch(getCsrf())
  data['_csrf'] = csrf
  return VideoApi.resendInvite(appId, data).then(res => res.data).catch(error => postErrorHandle(dispatch, undefined, error.response, {orgId: getState().urlReducer.org}))
}

export const loader = (flag) => (dispatch, getState) => {
  const selectedFilterReducer = JSON.parse(JSON.stringify(getState().selectedFilterReducer))
  selectedFilterReducer.loader = flag
  dispatch(selectedFilter(selectedFilterReducer))
}

export const inviteDeveloper = (data, appId) => async (dispatch, getState) => {
  let csrf = await dispatch(getCsrf())
  data['_csrf'] = csrf
  let checklist = getState().appChecklistReducer
  return VideoApi.inviteDeveloper(data, appId).then(res => {
    if (!checklist.isMemberInvited) {
      checklist.isMemberInvited = true
      dispatch(gotAppCheckList(checklist))
    }
    return res.data
  }).catch(error => postErrorHandle(dispatch, undefined, error.response, {orgId: getState().urlReducer.org || getState().currentAppReducer.orgId}))
}

export const setAnyKeyFlag = (key, flag) => (dispatch, getState) => {
  const selectedFilterReducer = JSON.parse(JSON.stringify(getState().selectedRuleReducer))
  selectedFilterReducer[key] = flag
  dispatch(selectedFilter(selectedFilterReducer))
}
